// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        // 1. Restrict to admissible domain (same as original contract: _tos.length > 0)
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));

        // 2. Setup: ensure calls do not revert due to external contract behavior
        // Deploy a mock that successfully returns true for transferFrom
        // But we cannot use vm.mockCall. Instead, deploy a simple compliant contract
        // Actually we cannot import external mock, we'll use caddress as a precompile or allow revert in catch
        // We catch revert and check return value

        // Perform the transfer call and capture both success and return value
        bool success;
        bool retVal;
        try c.transfer(from, caddress, _tos, v) returns (bool _ret) {
            success = true;
            retVal = _ret;
        } catch {
            success = false;
            // if revert, we consider the property undefined; we only care about non-reverting paths
            // but the property says: if it does not revert, return value must be true
        }

        // 3. Assert: whenever transfer does NOT revert, the return value MUST be true
        assertTrue(!success || retVal);
    }
}
